class Dog {
  String name;
  public static void main(String[] args) {
    Dog dog1 = new Dog();
    dog1.bark();                 // null says Ruff!（还没设 name）
    dog1.name = "Bart";
    Dog[] myDogs = new Dog[3];
    myDogs[0] = new Dog();
    myDogs[1] = new Dog();
    myDogs[2] = dog1;            // 别名：myDogs[2] 和 dog1 指向同一只狗
    myDogs[0].name = "Fred";
    myDogs[1].name = "Marge";
    System.out.println("last dog's name is " + myDogs[2].name);  // Bart
    int x = 0;
    while (x < myDogs.length) {
      myDogs[x].bark();
      x = x + 1;
    }
  }
  public void bark() {
    System.out.println(name + " says Ruff!");
  }
}
// 输出：null says Ruff! / last dog's name is Bart
//       Fred says Ruff! / Marge says Ruff! / Bart says Ruff!

