class Triangle {
  double area;
  int height;
  int length;
  public static void main(String[] args) {
    int x = 0;
    Triangle[] ta = new Triangle[4];
    while (x < 4) {
      ta[x] = new Triangle();
      ta[x].height = (x + 1) * 2;
      ta[x].length = x + 4;
      ta[x].setArea();
      System.out.println("triangle " + x + ", area = " + ta[x].area);
      x = x + 1;
    }
    int y = x;              // y=4（值复制）
    x = 27;                 // y 仍是 4
    Triangle t5 = ta[2];    // 引用复制：t5 和 ta[2] 是别名
    ta[2].area = 343;
    System.out.println("y = " + y + ", t5 area = " + t5.area);
    // y = 4, t5 area = 343.0
  }
  void setArea() { area = (height * length) / 2; }
}

